import{_ as r,l as n,o as e,c as l,v as i,p as E,x as t,d as s,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"恩格尔曲线","description":"","frontmatter":{"title":"恩格尔曲线","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/engel-curves.md","filePath":"econ/engel-curves.md","lastUpdated":1789023840000}'),d={name:"econ/engel-curves.md"};function c(B,a,g,h,u,m){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="恩格尔曲线" tabindex="-1">恩格尔曲线 <a class="header-anchor" href="#恩格尔曲线" aria-label="Permalink to &quot;恩格尔曲线&quot;">​</a></h1><div class="epigraph"><p>价格钉住之后，需求对财富的整条路径才叫恩格尔曲线。局部的正常或劣等，只是这条路径在一点的斜率。</p><footer>—— 据 Engel, Die Productions- und Consumtionsverhältnisse des Königreichs Sachsen, 1857；Working, Statistical Laws of Family Expenditure, QJE, 1943 整理</footer></div><p><a href="/econ/giffen-inferior">上一课</a>把 \\(\\partial x_i/\\partial w\\) 的符号收成正常、劣等，并标明吉芬是收入项压过替代。本课不重写斯勒茨基恒等式，也不再证明吉芬必须先劣等。缺口是：符号是一个点上的导数，后课份额、加总、福利比较要的是<strong>整条收入路径</strong>。固定 \\(p\\)，把 \\(x_i(p,w)\\) 看成 \\(w\\) 的函数，就是恩格尔曲线。Engel 的经验规律与 Working 的份额形式，都是这条路径的形状约束，不是另一种偏好公理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课只问 \\(\\partial x_i/\\partial w\\) 正还是负。同一商品可以在低收入劣等、高收入正常，也可以始终正常但弹性从大于一变成小于一。把这些写成「有时吉芬」，会把路径与一点的切线混起来。缺口是对象升级：恩格尔曲线 \\(w\\mapsto x_i(p,w)\\)，以及支出份额 \\(\\omega_i(p,w)=p_i x_i(p,w)/w\\)。</p><p>Engel 定律：食品份额随总支出下降——食品是必需品，收入弹性小于一。Working 把份额写成财富的仿射函数 \\(\\omega_i=\\alpha_i+\\beta_i\\log w\\)，是可估的恩格尔形状，不是从效用推出来的定理。本课要的是：局部符号如何嵌进这条路径，以及位似把路径收成过原点的射线。</p><h3 id="收入扩张路径不是马歇尔曲线" tabindex="-1">收入扩张路径不是马歇尔曲线 <a class="header-anchor" href="#收入扩张路径不是马歇尔曲线" aria-label="Permalink to &quot;收入扩张路径不是马歇尔曲线&quot;">​</a></h3><p>收入扩张路径（IEP）是 \\(w\\) 变动时 \\(x(p,w)\\) 在商品空间里扫出的轨迹。恩格尔曲线是 IEP 在单一坐标上的投影。马歇尔需求曲线钉住 \\(w\\) 动 \\(p\\)，二者正交。上一课的吉芬是马歇尔曲线向上；本课的劣等是恩格尔曲线局部向下。不要把两条曲线画成一张。</p><p><span class="marginnote">必需品：收入弹性 \\(\\eta_i\\lt 1\\)，份额随 \\(w\\) 下降。奢侈品 \\(\\eta_i\\gt 1\\)，份额上升。加总 \\(\\sum_i\\omega_i\\eta_i=1\\)，不能所有商品都是奢侈品。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定 \\(p\\)，对 \\(w\\) 求导或直接画 \\(x_i(w)\\)。位似：\\(x(p,w)=w\\,x(p,1)\\)，恩格尔是过原点的直线，所有 \\(\\eta_i=1\\)，Engel 定律被关掉——上一课已经用这一点排除劣等。拟线性：非计价物的恩格尔是水平线，\\(\\eta_i=0\\)（计价物内点），份额随 \\(w\\) 下降。CES、Cobb–Douglas 都在位似刀上，恩格尔是射线。</p><p>Working 形式允许 \\(\\beta_i\\neq 0\\)，份额随 \\(\\log w\\) 动，对应非位似。它仍是描述，不一定可积回某一 \\(u\\)；后课可积性会问整条 \\(x(p,w)\\)，不只问一条恩格尔。本课不估计 \\(\\beta_i\\)。</p>',12)),(e(),E(_,null,{default:t(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GIFF%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%B8%80%E7%82%B9%E4%B8%8A%E7%9A%84%20%E2%88%82x%2F%E2%88%82w%22%5D%20--%3E%20ENG%5B%22%E6%81%A9%E6%A0%BC%E5%B0%94%EF%BC%9A%E6%95%B4%E6%9D%A1%20x_i(w)%22%5D%0A%20%20ENG%20--%3E%20NEC%5B%22%CE%B7%20%EF%BC%9C%201%EF%BC%9A%E5%BF%85%E9%9C%80%E5%93%81%EF%BC%8C%E4%BB%BD%E9%A2%9D%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ENG%20--%3E%20LUX%5B%22%CE%B7%20%3E%201%EF%BC%9A%E5%A5%A2%E4%BE%88%E5%93%81%22%5D%0A%20%20ENG%20--%3E%20HOM%5B%22%E4%BD%8D%E4%BC%BC%EF%BC%9A%E5%B0%84%E7%BA%BF%EF%BC%8C%CE%B7%20%3D%201%22%5D%0A%20%20ENG%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AEV%2FCV%20%E7%94%A8%E6%94%B6%E5%85%A5%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>两商品时，IEP 与预算线的交点随 \\(w\\) 外移。劣等段上，该商品的恩格尔向下，另一商品必须「更正常」，瓦尔拉斯定律才能保住。\\(n\\) 种商品时，几种同时弯曲完全可以。份额语言与<a href="/econ/ces-cobb-douglas">Cobb–Douglas</a>的恒定份额对照：那里 \\(\\eta_i=1\\)，本课允许 \\(\\eta_i\\) 随 \\(w\\) 变。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>财富增加沿 IEP 走，不沿无差异面。相对价格没变，动的是规模与结构。非位似时，结构随 \\(w\\) 变：先满足必需品，再进入奢侈品，这正是 Engel 看到的食品份额下降。Working 用半对数份额把这条弯曲写成可估的直线，方便加总比较，并不声称 \\(\\beta_i\\) 是偏好参数。</p><p>与吉芬的接口：吉芬要劣等<strong>且</strong>占预算够大。恩格尔曲线告诉你劣等发生在哪一段 \\(w\\)、那一段的份额够不够大。一点上的符号表没有这段几何。涨价比较静态仍回斯勒茨基；本课只提供收入方向的全局图。</p><p><span class="marginnote">家庭规模、相对价格都会扭曲线。Engel 的原始表是支出与食品，不是现代 \\(x(p,w)\\) 的 \\(ceteris\\ paribus\\)。引用定律时当定性，不当恒等式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>角点：低收入时某些 \\(x_i=0\\)，恩格尔先贴轴再离开，弹性在进入点没有定义。加总家庭的「市场恩格尔」混合了偏好与收入分布，不必像任何一个人。Gorman 加总要求恩格尔仿射且斜率可加，那是后课；本课只承认个人路径可以弯。</p><p>也不要把恩格尔写成限价簿上的存量–收入关系。这里 \\(w\\) 是消费者财富，没有报价。跨期、劳动收入若被塞进静态 \\(w\\)，曲线会吸收储蓄与工资，对象切错。</p><p>Working 之后 Leser 把份额对 \\(\\log w\\) 的仿射叫 Working–Leser 形式，几乎同一条线。它便于估 \\(\\beta_i\\)，仍不保证可积。下一课的 EV/CV 夹缝方向，读的正是本课的 \\(\\eta_i\\)：正常则两条货币度量分道，位似射线则分道方式更整齐，拟线性水平恩格尔则重合。</p><p>后课默认：谈到收入效应，可以把它升成整条恩格尔曲线；位似等于射线，Engel 定律需要非位似。下一课的等价与补偿变化，正是沿不同财富路径读货币度量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恩格尔曲线是固定价格下需求对财富的路径；正常/劣等是一点的斜率。</li><li>必需品份额下降、奢侈品份额上升；位似把所有弹性钉成 \\(1\\)。</li><li>Working 份额对 \\(\\log w\\) 仿射，是可估形状，不是新公理。</li><li>吉芬仍要劣等且份额够大；路径告诉你发生在哪一段。</li><li>出处：Engel, 1857；Working, <em>QJE</em>, 1943；Varian；Mas-Colell, Whinston and Green。</li></ul>',12))])}const C=r(d,[["render",c]]);export{A as __pageData,C as default};
